INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', '【互换】魔法', 'concept', '【互换】魔法is佐伯米莉亚''s magic, speculated by二阶堂希罗to be related to精神共享and to have失控, causing the sharing of memories and other elements.', X'');
