INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Witch Factor', 'concept', 'The essence of a witch, which needs to be removed or reconstituted according to the proposed plan.<SEP>Witch Factor is a weapon-like element spread by月代雪throughout the global human population, capable of triggering a transformation into immortal monsters known as Witches.<SEP>Witch Factor is a malicious substance spread by Yuki into humanity to turn people into tools and is central to the revenge plan.<SEP>The Witch Factor is a substance that has diffused and spread to all humans, a key element in月代雪''s plan.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'The Great Witch', 'person', 'A powerful witch who transformed into Witch Factor and is sought to be revived, though she plots revenge against humanity.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Meilulu', 'person', 'A character referenced by Niro as the source of information about the Great Witch''s transformation.', X'');
