INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Previous Worlds', 'concept', 'Previous Worlds refer to the alternate realities or timelines that二阶堂希罗claims to have experienced, where different events occurred.', X'');
