INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Cold Reading', 'method', 'Cold Reading is a technique mentioned by宝生玛格to describe二阶堂希罗''s initial claims as potentially generic psychological manipulation.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Prison', 'location', 'The Prison is the location where二阶堂希罗and the others are held as captives, both in the current and previous experiences.<SEP>Prison is referenced as the监牢(prison) from which二阶堂希罗expresses a desire for everyone to escape together without resorting to violence.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Provisional Witches', 'concept', 'Provisional Witches refers to the status of the少女(young women) in the story, whose thoughts are said to become violent and exclusive.', X'');
