INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', '原初的魔女', 'concept', '原初的魔女refers to the primordial witches, the original inhabitants of the island who were high-level beings capable of magic.<SEP>原初的魔女refers to the original witches of the island, a group to which冰上梅露露claims to be the last surviving member.<SEP>The original witch who was eradicated from the world by humanity, forming the basis for the accusation against humans.<SEP>The original witches are a superior race to humans, as claimed by月代雪.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', '信', 'artifact', '信is a letter found by二阶堂希罗, written by an island resident, containing information about the Great Witch adopting a human girl.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', '人类少女', 'person', '人类少女is a human girl who was adopted by the Great Witch according to the letter found by二阶堂希罗.', X'');
