INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', '固定视线的魔法', 'method', '固定视线的魔法(Gaze-Fixing Magic) is a specific type of magic that二阶堂希罗accuses莲见蕾雅of using to captivate audiences and maintain her stardom.', X'');
