INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', '内心世界', 'concept', 'The inner world is the psychological space of城崎诺亚that二阶堂希罗aims to access to emotionally destabilize her.', X'');
