INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Humanity', 'concept', 'The Great Witch is plotting revenge against humanity, a fact acknowledged even by those who seek to revive her.<SEP>Humanity is the collective human species targeted by月代雪''s plan, having been deeply infiltrated by Witch Factor and facing transformation and extinction.<SEP>Humanity is the collective target of Yuki''s revenge plan, destined for extermination through the activation of the Witch-Killing Magic.<SEP>Humanity is the collective target of月代雪''s plan, destined for extinction through the use of the "Magic to Kill Witches" as a form of retribution for exterminating witches.', X'');
