INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Family', 'concept', 'A concept of kinship and belonging, questioned by a character seeking validation from another who raised her.<SEP>Family is a concept discussed by multiple characters, representing a newfound appreciation and a reason to return home.', X'');
INSERT INTO entities (timeline_id, entity_name, entity_type, description, vector) VALUES ('3rd_Loop', 'Friendship', 'concept', 'Friendship is a central theme as the characters affirm their bonds, plan future meetings, and offer collective support to one another.', X'');
