INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 10, '希罗', '旁白', 'The narrator (旁白) states they were always following希罗and felt they could do nothing without her, highlighting a deep dependency that ended when they were separated in middle school.<SEP>旁白expresses a desire to keep talking with希罗, indicating a close personal connection.', 2, X'');
