INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 21, '月代雪', '魔女', '月代雪identifies as a witch and uses the historical extinction of witches at human hands to justify the judgment and punishment of humanity.<SEP>月代雪identifies as a witch, claiming witches are rational beings, unlike humans, and seeks vengeance for their extermination.<SEP>月代雪is the sole survivor of the witches and carries the hatred and desire for vengeance of all the deceased witches.<SEP>月代雪identifies as a witch and describes the mortality and suffering of witches as a group.<SEP>月代雪uses the persecution and imprisonment of魔女on an岛as evidence of their difference from humans.<SEP>月代雪identifies herself as a witch, a being she claims is incompatible with humans.<SEP>月代雪worries that the魔女on the island might laugh at her and that those who died as魔女might resent her.', 7, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 22, '樱羽艾玛', '魔女', '樱羽艾玛questions the necessity of eliminating either witches or humans, arguing that it is wrong.', 1, X'');
