INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 24, '人类', '魔女', '魔女were hunted and killed by人类armies, destroying their peaceful existence, though coexistence is later proposed.', 1, X'');
