INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 50, '旁白', '樱羽艾玛', '旁白描述樱羽艾玛是一个同样孤立无援、难以接近的女孩，并期待因为共同的孤独能和她成为朋友。<SEP>旁白narrates樱羽艾玛''s internal thoughts and feelings, particularly regarding her pain over二阶堂希罗.', 2, X'');
