INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 295, '二阶堂希罗', '辩护的权利', '二阶堂希罗claims the right to defend for humanity, but this right is denied by月代雪on the grounds that witches never had such a right.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 296, 'Previous World', '二阶堂希罗', '二阶堂希罗gained knowledge from the Previous World, specifically hearing月代雪''s voice, which informs the current understanding of the Plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 297, '二阶堂希罗', '初中事件', '二阶堂希罗identifies the初中事件as the key moment where her actions, driven by jealousy, caused significant harm to樱羽艾玛.', 1, X'');
