INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 339, '佐伯米莉亚', '老师', '佐伯米莉亚states that she is trying to imitate her teacher, who helped her in the past and serves as her role model.<SEP>佐伯米莉亚feels her entire persona, including studying law and calling herself "大叔," is an imitation of her teacher, and she is conflicted about destroying what her teacher wanted to protect.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 340, '佐伯米莉亚', '魔女化', '佐伯米莉亚is nearing "魔女化" (witchification) as she battles her past psychological trauma, which二阶堂希罗observes.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 341, '佐伯米莉亚', '心理创伤', '佐伯米莉亚is actively fighting against her psychological trauma from past events, which is the core of her current distress.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 342, '佐伯米莉亚', '泽度可可', '佐伯米莉亚praises泽度可可, calling them了不起for their sentiment about family.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 343, 'Friendship', '佐伯米莉亚', '佐伯米莉亚asks if they will remain friends after returning, affirming the value of their bond.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 344, '人类', '佐伯米莉亚', '佐伯米莉亚argues against the premise of inherent human guilt and advocates for a proper judicial process for humanity.<SEP>佐伯米莉亚believes that humans reflect on their errors, learn, and grow to create a better future.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 345, 'Human Nature', '佐伯米莉亚', '佐伯米莉亚argues against the notion that humans are merely stupid and must be destroyed, stating that humans can learn, reflect, and reform after wrongdoing.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 346, 'Act03_Chapter02', '佐伯米莉亚', '佐伯米莉亚is a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 347, '人生而有罪', '佐伯米莉亚', '佐伯米莉亚directly references and challenges the concept that "humans are born with sin" as presented by the adversary.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 348, 'Judgment', '佐伯米莉亚', '佐伯米莉亚questions the legitimacy of月代雪''s judgment and suggests the possibility of a wrongful verdict.', 1, X'');
