INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 350, 'Grace Period', '佐伯米莉亚', '佐伯米莉亚pleads for the execution to be delayed further, questioning the sufficiency of the grace period.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 351, '幕后黑手', '黑部奈叶香', '黑部奈叶香came to the prison with the goal of taking revenge against the mastermind behind their situation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 352, '黑部奈叶香', '黑部奈叶香的姐姐', '黑部奈叶香is concerned about her sister, who is the jailer and a potential target for二阶堂希罗''s rescue plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 353, '大魔女', '黑部奈叶香', '黑部奈叶香directly asks二阶堂希罗if there is a way to kill the Great Witch, showing her focus on confronting the mastermind.<SEP>黑部奈叶香perceives the Great Witch''s power as overwhelming and believes defeating her is impossible.<SEP>黑部奈叶香has made preparations to defeat the Great Witch but prefers to act alone.<SEP>黑部奈叶香vows to defeat the Great Witch.<SEP>黑部奈叶香''s willingness to use magic to view夏目安安''s past is motivated by the goal of defeating大魔女.', 5, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 354, '宅邸', '黑部奈叶香', '黑部奈叶香expresses that being forcibly taken from the mansion was troublesome and shows little interest in returning to the outside world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 355, 'The Remnant', '黑部奈叶香', 'Nayeka has a personal stake in the matter as her sister is afflicted by the Remnant, driving her skepticism and questions.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 356, 'Cult Ritual', '黑部奈叶香', 'Nayeka criticizes the proposed revival plan by comparing it to a cult ritual, expressing deep distrust.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 357, 'B-Grade Horror Movie', '黑部奈叶香', 'Nayeka uses the cliché of a B-grade horror movie plot to express her skepticism about the feasibility of the revival plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 358, 'Sacrificial Victims', '黑部奈叶香', 'Nayeka expresses fear that the ritual''s success would lead to the participants becoming sacrificial victims.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 359, 'Hope', '黑部奈叶香', 'Nayeka distinguishes hope from mere optimism, expressing skepticism about the plan''s basis in genuine hope.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 360, 'The Great Witch', '黑部奈叶香', 'Nayeka accuses Niro of being a puppet manipulated by the Great Witch and doubts the witch''s intentions post-revival.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 361, '幻视', '黑部奈叶香', '黑部奈叶香possesses and utilizes the magic of Clairvoyance to see visions, including those of the Great Witch''s power.<SEP>黑部奈叶香possesses the magical ability to perform幻视, which is requested by二阶堂希罗to investigate夏目安安''s past.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 362, '姐姐', '黑部奈叶香', '黑部奈叶香is concerned for her sister, which is a point二阶堂希罗uses to motivate her.<SEP>黑部奈叶香''s sister sacrificed her life, which fuels her distrust of authority and her resolve to defeat the Great Witch alone.<SEP>黑部奈叶香''s psychological trauma is caused by her sister''s self-sacrificing protection.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 363, '祭品', '黑部奈叶香', '黑部奈叶香fears that they will be used as sacrificial offerings, leading to their deaths.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 364, '意志', '黑部奈叶香', '黑部奈叶香doubts whether their actions are of their own free will or manipulated by the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 365, '岛', '黑部奈叶香', '黑部奈叶香used her clairvoyance on the island to see visions of its past, related to the Great Witch''s power.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 366, '复制品', '黑部奈叶香', '黑部奈叶香uses the analogy of being a "copy" to explain why she believes they cannot defeat the "original" Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 367, '原版', '黑部奈叶香', '黑部奈叶香refers to the Great Witch as the "original" to signify her superior and unbeatable power compared to them.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 368, '赌局', '黑部奈叶香', '黑部奈叶香perceives二阶堂希罗''s plan to defeat the Great Witch as a reckless gamble she does not want to be part of.<SEP>黑部奈叶香refuses to be drawn into the risky gamble proposed by二阶堂希罗.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 369, '紫藤亚里沙', '黑部奈叶香', '黑部奈叶香reveals to二阶堂希罗that紫藤亚里沙''s sin is "纵火" (arson).<SEP>黑部奈叶香reveals to二阶堂希罗that紫藤亚里沙''s crime was arson and that her parents covered it up.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 370, '这个国家的权势', '黑部奈叶香', '黑部奈叶香distrusts the country''s authorities, believing they will not help and were responsible for her sister''s sacrifice.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 371, '友情游戏', '黑部奈叶香', '黑部奈叶香explicitly rejects participating in what she calls a "friendship game," emphasizing her solitary approach.<SEP>黑部奈叶香explicitly states she does not intend to play the friendship game.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 372, '宝生玛格', '黑部奈叶香', '黑部奈叶香and宝生玛格agree in their assessment that二阶堂希罗does not seem like an enemy monster.<SEP>黑部奈叶香agrees with and elaborates on宝生玛格''s point about the sunk cost, noting that past efforts would be wasted.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 373, '魔女化', '黑部奈叶香', '黑部奈叶香is the subject of a planned witch transformation, which she resists.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 374, '异形', '黑部奈叶香', '黑部奈叶香transformed into an异形after her execution, as remembered by二阶堂希罗.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 375, '魔女因子', '黑部奈叶香', '黑部奈叶香explains that the Witch Factor is the element that constituted their witch forms and has now disappeared.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 376, '夏目安安', '黑部奈叶香', '黑部奈叶香uses magic to glimpse into夏目安安''s past, revealing details about her family and the effects of brainwashing magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 377, '心理创伤', '黑部奈叶香', '黑部奈叶香possesses a psychological trauma related to the self-sacrifice of others, which makes her vulnerable to manipulation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 378, '遗言', '黑部奈叶香', '黑部奈叶香created a遗言which expressed her wish that no one else should sacrifice themselves.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 379, '冰上梅露露', '黑部奈叶香', '黑部奈叶香states that their survival is ironically due to冰上梅露露''s plan to use them to find the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 380, '肉块', '黑部奈叶香', '黑部奈叶香observes that a bullet fired at the flesh mass burned up in mid-air.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 381, '泽度可可', '黑部奈叶香', '黑部奈叶香uses her幻视魔法to uncover and reveal泽度可可''s past as a survivor of the除夕夜连续无差别杀伤案.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 382, '幻视魔法', '黑部奈叶香', '黑部奈叶香employs her幻视魔法to gain knowledge about泽度可可''s past connection to the murder case.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 383, '月代雪', '黑部奈叶香', '黑部奈叶香acknowledges月代雪''s capability as the大魔女and is addressed by her with a mention of her sister.<SEP>黑部奈叶香suggests to月代雪that spending a little more time together is not bad, despite the inevitable outcome.<SEP>黑部奈叶香hypothesizes that月代雪''s existence and actions are in a state of self-contradiction.<SEP>黑部奈叶香questions月代雪about whether her actions are driven by emotions.<SEP>黑部奈叶香observes that月代雪lacked the courage to act and instead entrusted the magic to樱羽艾玛.<SEP>黑部奈叶香observes that月代雪has listened to their劝说.', 6, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 384, '恐惧', '黑部奈叶香', '黑部奈叶香explains that fear comes from the unknown and can be resolved through understanding.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 385, 'Act03_Chapter02', '黑部奈叶香', '黑部奈叶香is listed as a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 386, 'The Mansion', '黑部奈叶香', '黑部奈叶香decides to stay at The Mansion temporarily to care for others but will leave due to painful memories associated with the place.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 387, 'Past Memories', '黑部奈叶香', '黑部奈叶香states she cannot actively retrieve specific past memories of the island.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 388, '复仇', '黑部奈叶香', '黑部奈叶香understands the pain of abandoning复仇due to the sunk costs involved.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 389, '未知', '黑部奈叶香', '黑部奈叶香states that the unknown is a source of fear.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 390, '银子弹', '黑部奈叶香', '黑部奈叶香states that a silver bullet is the necessary weapon to fight and pierce evil spirits.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 391, '冰上梅露露', '残骸', '冰上梅露露explains that a Husk is the empty shell left after the Witch Factor consumes a soul.<SEP>冰上梅露露states that captured girls cannot leave the prison until they turn into witches and become残骸.<SEP>冰上梅露露provided the information that the Remains are the hollow shells of witches eroded by the Witch Factor.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 392, '残骸', '魔女因子', 'The Witch Factor curse is intended to turn its subject into a Remnant, after which it transfers to a new girl.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 393, '审判庭', '看守', '看守closes the main door of the审判庭after confirming冰上梅露露''s arrival.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 394, '冰上梅露露', '幕后黑手', '冰上梅露露describes herself as the unseen mastermind who has been waiting in the prison.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 395, '未知角色', '魔女图鉴', 'The relation (未知角色, 魔女图鉴) describes a recurring narrative action where an unidentified character announces updates to a specific artifact or record known as the "魔女图鉴" (Witch Encyclopedia). This announcement consistently serves as a system-like notification within the story''s magical context. The updates to the compendium are directly triggered by significant magical events, most notably the transformations of specific characters, including 冰上梅露露 (Hinata Meruru), 城崎诺亚 (Shirosaki Noah), and 橘雪莉 (Tachibana Sherry). Each announcement indicates that new information about these witches or their powers has been added, recorded, and integrated into the encyclopedia, marking a clear progression in the magical narrative. The relation underscores the 魔女图鉴''s role as a dynamic, living document within this universe, maintained and updated by an unknown entity in response to key plot developments.', 11, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 396, 'The Mansion', '未知角色', 'The unknown character mentions that young girls were gathered to the mansion.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 397, '未知角色', '讨论会', '未知角色intervenes in the讨论会, encouraging all participants to speak freely and break the imposed silence.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 398, '旁白', '未知角色', '旁白describes the未知角色sighing lightly amidst the chaotic situation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 399, '大魔女', '未知角色', 'An unknown character addresses the flesh mass as "大魔女大人" (Great Witch), expressing reverence.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 400, '橘雪莉', '远野汉娜', '远野汉娜feels profound guilt over events involving橘雪莉, believing橘雪莉chose to accompany her in her sin.<SEP>橘雪莉killed远野汉娜, which is framed as fulfilling远野汉娜''s wish to avoid becoming a witch, but also causes橘雪莉great internal conflict.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 401, '远野汉娜', '魔女化', '远野汉娜''s魔女化was deepening during the past events, which is cited as a factor in her actions.<SEP>远野汉娜explicitly states she does not want to become a witch and wishes to resist that predetermined fate.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 402, '既定命运', '远野汉娜', '远野汉娜expresses a desire not to willingly accept the predetermined fate scripted by the prison.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 403, '监牢', '远野汉娜', '远野汉娜is within a监牢that scripts a fate she wishes to反抗against.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 404, '紫藤亚里沙', '远野汉娜', '紫藤亚里沙and远野汉娜both demand an explanation from二阶堂希罗about her intentions.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 405, 'Guilt', '远野汉娜', '远野汉娜is overwhelmed by guilt for killing蕾雅and艾玛, leading to her mental breakdown.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 406, '蕾雅', '远野汉娜', '远野汉娜killed蕾雅, which is a source of her intense guilt.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 407, '艾玛', '远野汉娜', '远野汉娜killed艾玛, which is a source of her intense guilt.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 408, '远野汉娜', '雪莉', '远野汉娜feels additional guilt because雪莉is willing to accompany her despite her crimes.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 409, '心', '远野汉娜', '远野汉娜''s心is described as being unable to承受不住负担the burden of her guilt.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 410, '远野汉娜', '重力', '远野汉娜''s失控的魔法causes重力to become紊乱, creating a dangerous situation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 411, '岛', '远野汉娜', '远野汉娜''s失控的魔法is causing the岛to rise continuously in height.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 412, '另一个世界的我们', '远野汉娜', '远野汉娜feels a moral obligation to永远记住and mourn the alternate versions of themselves, 另一个世界的我们.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 413, '远野汉娜', '魔女因子', '远野汉娜''s past murderous actions were influenced by the corrupting murderous impulses of the魔女因子.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 414, '心理创伤', '远野汉娜', '远野汉娜''s psychological trauma is the central issue causing her despair and is the key to persuading her.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 415, '自责感', '远野汉娜', '远野汉娜is being crushed by feelings of guilt and self-blame.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 416, '怪物', '远野汉娜', '远野汉娜expresses a deep fear of turning into a monster, both physically and mentally, if she accepts certain justifications.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 417, '生命', '远野汉娜', '远野汉娜emphasizes the singular value and irreplaceability of human life, arguing against easily moving on from past deaths.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 418, '远野汉娜', '魔法', '远野汉娜points to her own ability as an example that magic users exist.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 419, 'Tea Party', '远野汉娜', '远野汉娜proposes and reminds others of their promise to have a tea party at莲见蕾雅''s home.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 420, 'Human Nature', '远野汉娜', '远野汉娜defends human nature by stating that weakness drives the pursuit of nobility and the ability to stand up again, encouraging月代雪to do the same.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 421, 'Act03_Chapter02', '远野汉娜', '远野汉娜is a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 422, '直升机', '远野汉娜', '远野汉娜hopes the helicopter means they are finally being picked up to go home.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 423, '审判', '远野汉娜', '远野汉娜在审判的背景下感到绝望，质疑她们所做的一切是否都是徒劳的。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 424, '人类', '远野汉娜', '远野汉娜supports the idea that the desire to remain noble represents human goodness.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 425, '月代雪', '远野汉娜', '远野汉娜proposes that pointing out contradictions to月代雪could make her reconsider her plans.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 426, '世界之敌', '预备魔女', 'A预备魔女is designated as a世界之敌because they carry the魔女因子, which is destructive to humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 427, '预备魔女', '魔女因子', 'A预备魔女carries the魔女因子, which is the key element that leads to their potential transformation into a witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 428, '月代雪', '预备魔女', '月代雪observes that girls become预备魔女after mental breakdowns, an unexpected effect of the witch factor.<SEP>月代雪states she must adjust the number of Apprentice Witches to prevent excessive human vigilance.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 429, '监牢', '预备魔女', 'Apprentice Witches are gathered and imprisoned in a prison because their magic is considered dangerous.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 430, '预备魔女', '魔法', 'Apprentice Witches possess magic that is considered very dangerous by people.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 431, '宝生玛格', '杀人冲动', '宝生玛格uses the concept of杀人冲动to logically accuse二阶堂希罗of having had the impulse to kill, challenging her trustworthiness.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 432, '杀人冲动', '紫藤亚里沙', '紫藤亚里沙believes that the杀人冲动(murderous impulse) will inevitably consume everyone, justifying her call for immediate death.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 433, 'The Environment', '夏目安安', '夏目安安believes she should be confined in the environment, viewing it as a necessary prison to protect others from her dependence.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 434, 'Dependence', '夏目安安', '夏目安安acknowledges the inevitability of human dependence but fears it, leading to her desire for isolation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 435, '夏目安安', '洗脑', '夏目安安uses the洗脑magic, a verbal suggestion, in an attempt to silence others during the discussion.<SEP>夏目安安identifies the magic月代雪is using as being the same type as their own magic.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 436, '夏目安安', '宝生玛格', '宝生玛格uses her模仿magic to counteract夏目安安''s洗脑magic and challenges夏目安安''s dependence on magic for communication.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 437, '夏目安安', '泽度可可', '泽度可可confronts夏目安安, warning her that she will die easily in their current situation and has seen her fate in parallel worlds.<SEP>夏目安安uses a command to silence and later allow泽度可可to speak, to which泽度可可reacts.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 438, '夏目安安', '紫藤亚里沙', '夏目安安uses the command magic "不许杀人" and the effort "听进去" to try to stop紫藤亚里沙from killing.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 439, '夏目安安', '米莉亚', '夏目安安expresses a resolve to stop or protect米莉亚, among others.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 440, '夏目安安', '诺亚', '夏目安安expresses a resolve to stop or protect诺亚, among others.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 441, '夏目安安', '魔法', '夏目安安notes that in their current environment, using magic does not draw strange looks, making it more comfortable.<SEP>夏目安安associates her ability to use magic with the oppression and discrimination she has suffered, viewing it as the cause of her misery.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 442, '夏目安安', '监狱', '夏目安安views the prison as a preferable refuge from the outside world, where she believes no positive change is possible for her.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 443, '夏目安安', '宅邸', '夏目安安claims the mansion is sufficient for her needs, with its own sky and sunlight, and explicitly rejects the need for the outside world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 444, '夏目安安', '未来', '夏目安安explicitly states that her future holds only despair and that no happiness exists for her, rejecting the possibility of positive change.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 445, '夏目安安', '绝望', '夏目安安believes that despair is inevitable in her future, which renders any action she takes beforehand meaningless and futile.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 446, '夏目安安', '旁白', '旁白describes夏目安安''s state of denying reality and repeating that it must be a dream.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 447, '夏目安安', '过去', '夏目安安vehemently rejects her past, wanting to burn and forget it, as she associates it with failure and trauma.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 448, '夏目安安', '罪孽', '夏目安安is burdened by a past罪孽involving her parents, which she tries to deny and escape from.<SEP>夏目安安is in denial about her罪孽, specifically the fact she destroyed her parents, which二阶堂希罗states she must face.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 449, '夏目安安', '洗脑魔法', '夏目安安''s family was subjected to洗脑魔法, a fact revealed by黑部奈叶香, though夏目安安denies being a victim and claims she acted voluntarily.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 450, '双亲', '夏目安安', '夏目安安is revealed to have destroyed her双亲, a fact that constitutes her central trauma and罪孽, which she denies and refuses to face.<SEP>二阶堂希罗accuses夏目安安of having destroyed her双亲, a fact that constitutes her core罪孽which she must face.<SEP>夏目安安is described as having personally destroyed their happy family with their双亲, an act for which they carry guilt.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 451, '夏目安安', '故事', '夏目安安is skilled at writing故事, which二阶堂希罗identifies as evidence that her interests are oriented toward the outside world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 452, '夏目安安', '孤独与静寂', '夏目安安repeatedly states that her true desire is for deep孤独与静寂, rejecting all forms of companionship and comfort.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 453, '夏目安安', '监牢', '夏目安安is confined in a监牢, where she claims she wants to be left alone to幻想故事的世界.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 454, '单人牢房', '夏目安安', '夏目安安describes her单人牢房as a place where she can retreat into幻想故事的世界and spend time in微眠, claiming she needs nothing else.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 455, '夏目安安', '微眠', '夏目安安states she can spend her time in微眠within her单人牢房, suggesting it is a method of escapism from her reality.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 456, '夏目安安', '幸福', '夏目安安is characterized as being afraid of幸福due to past trauma, leading them to actively avoid it and remain in a state of不幸.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 457, '不幸', '夏目安安', '夏目安安is accused of being a dependent who immerses themselves in their own不幸, which二阶堂希罗warns will lead to eternal loneliness.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 458, '夏目安安', '肉块', '夏目安安notices the轮廓(silhouette) of a person, which is later revealed to be the flesh mass, within the blood.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 459, '夏目安安', '外面的世界', '夏目安安questions the importance and necessity of returning to the outside world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 460, '原本的生活', '夏目安安', '夏目安安expresses a lack of attachment to her original life, contributing to her refusal to cooperate.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 461, '人际关系', '夏目安安', '夏目安安states that the absence of troublesome interpersonal relationships makes the current environment more comfortable.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 462, '夏目安安', '月代雪', '夏目安安suggests that if their magic works, persuading月代雪could influence her actions.<SEP>夏目安安observes that月代雪, who talks of exterminating humans, acts in a very human-like manner.<SEP>夏目安安encourages月代雪to start over and rethink her stance.<SEP>夏目安安tells月代雪not to escape, to think, and to open her eyes to her own behavior.', 4, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 463, 'Act03_Chapter02', '夏目安安', '夏目安安is a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 464, '夏目安安', '夏目安安的魔法', '夏目安安possesses a magic ability that requires convincing the target to be effective.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 465, '城崎诺亚', '夏目安安', '夏目安安corrects城崎诺亚, stating the mansion should be a dark castle instead of rainbow-colored.<SEP>夏目安安disagrees with城崎诺亚''s rainbow color plan, wanting a dark castle instead, leading to a "firm struggle".', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 466, '夏目安安', '审判', '夏目安安questions the validity of the trial and demands that proper discussion take place before a conclusion is reached, holding月代雪accountable for her words.<SEP>夏目安安challenges others to continue the trial if they cannot refute her statement.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 467, 'Magic', '夏目安安', '夏目安安states her persuasion magic requires the target to already be somewhat convinced of her credibility.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 468, 'Information To Persuade', '夏目安安', '夏目安安states that her magic requires finding information that can convince月代雪to be effective.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 469, '夏目安安', '监牢的管理方', '夏目安安质疑这座监牢的管理方是否就是把她们关在这里的人类。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 470, '冰上梅露露', '夏目安安', '夏目安安criticizes the decision to ask冰上梅露露for advice, stating it was a mistake.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 471, '橘雪莉', '身份认同', '橘雪莉''s sense of self is questioned by二阶堂希罗, who suggests it may be tied to her own misfortune, leading to橘雪莉''s expressions of self-hatred.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 472, '冰上梅露露', '泽度可可', '泽度可可finds冰上梅露露suspicious and questions her involvement.<SEP>冰上梅露露comforts泽度可可and states an intention to heal her.<SEP>冰上梅露露expresses concern for泽度可可''s well-being by calling out to her.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 473, '冰上梅露露', '大魔女', '冰上梅露露expresses a desire and reverence to meet the大魔女.<SEP>冰上梅露露addresses the flesh mass as the Great Witch, expressing joy at finally meeting her.<SEP>冰上梅露露was recognized by the Great Witch, who granted her magic for protection, making her a witch and part of the Great Witch''s family.<SEP>冰上梅露露believes the Great Witch transformed into witch factor and is hiding among humans, and she is searching for her.<SEP>The Great Witch used冰上梅露露as a test subject for the Witch Factor curse, which二阶堂希罗argues was not an act of love but exploitation.<SEP>冰上梅露露''s entire existence is defined by her desperate need to reunite with the Great Witch, whom she considers family.', 6, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 474, '冰上梅露露', '预备魔女的少女们', '冰上梅露露is accused of manipulating the girls who are candidates to become witches, making them fight each other.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 475, '冰上梅露露', '城崎诺亚', '冰上梅露露attempts to comfort城崎诺亚following her emotional breakdown, as instructed by二阶堂希罗.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 476, '冰上梅露露', '旁白', '旁白describes冰上梅露露''s reaction, such as her eyes widening in surprise.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 477, 'The Prison', '冰上梅露露', '冰上梅露露states she has been waiting in the prison for the arrival of the others.<SEP>冰上梅露露confirms that the prison is inescapable and no captured girl has ever successfully escaped.<SEP>冰上梅露露describes the prison as an inescapable place for captured girls, including herself.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 478, '冰上梅露露', '魔女安息仪式', '冰上梅露露is implied to have known about the ritual''s requirement for 13 witches and may have gathered the participants for this purpose.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 479, '冰上梅露露', '原初的魔女', '冰上梅露露reveals herself as the last remaining Primordial Witch, an original inhabitant of the island.<SEP>冰上梅露露claims to be the last surviving member of the original witches of the island.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 480, '冰上梅露露', '岛', '冰上梅露露lives on the island and became a witch there.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 481, '人类', '冰上梅露露', '冰上梅露露admits she was originally human before being transformed into a witch by the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 482, '冰上梅露露', '魔女审判', '冰上梅露露gives approval for the witch trial to proceed when questioned by典狱长.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 483, '冰上梅露露', '魔女因子', '冰上梅露露explains that the Witch Factor is bestowed by the Great Witch and activates during witch transformation.<SEP>冰上梅露露was a subject of the Witch Factor curse but failed to become a Remnant and did not spread the curse to others.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 484, '冰上梅露露', '孤岛', '冰上梅露露speculates that witches likely migrated to the孤岛(isolated island) rather than appearing there naturally.<SEP>冰上梅露露has been living quietly on the isolated island, which二阶堂希罗cites as evidence of her being a failed experiment.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 485, '冰上梅露露', '宝生玛格', '宝生玛格rejects冰上梅露露''s attempt to approach and treat her, insisting she is fine.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 486, '冰上梅露露', '魔女化', '冰上梅露露is explaining the concepts of精神的魔女化and肉体的魔女化to二阶堂希罗.<SEP>冰上梅露露describes witch transformation as a process where spirit and body change, potentially leading to becoming a Husk.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 487, '冰上梅露露', '大魔女大人', '冰上梅露露mentions that the Great Witch bestowed the Witch Factor and lived with the primordial witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 488, '冰上梅露露', '召唤大魔女大人的仪式', '冰上梅露露is determined to continue the ritual to summon the Great Witch, fearing personal collapse if she gives up.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 489, '冰上梅露露', '貌似丑陋怪物的魔女形象', '冰上梅露露states that the process of魔女化(witchification) recreates the fictional貌似丑陋怪物的魔女形象(witch image resembling an ugly monster).', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 490, '冰上梅露露', '治疗魔法', '冰上梅露露possesses and uses healing magic, potentially applying it to both physical wounds and psychological trauma.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 491, '冰上梅露露', '召唤大魔女仪式', 'Despite her trauma, 冰上梅露露insists on continuing the ritual to summon the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 492, '冰上梅露露', '玛格小姐', '冰上梅露露uses her healing magic in a desperate attempt to save玛格小姐from fatal wounds.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 493, '冰上梅露露', '月代雪', '月代雪found and raised冰上梅露露, and there is a hypothesis that she later used her as an experimental subject involving魔女因子.<SEP>月代雪''s plan to exterminate humanity does not include冰上梅露露because she is not human but a witch, showing月代雪cannot trample on冰上梅露露''s feelings.<SEP>冰上梅露露was saved and raised by月代雪, who called her family; 冰上梅露露seeks the truth about this bond and asks月代雪to end her life if it was a lie.<SEP>冰上梅露露declares unwavering loyalty to月代雪, respecting her choices and considering her family.<SEP>月代雪apologizes to冰上梅露露for involving her, and they share a final moment together before disappearing.', 5, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 494, 'Act03_Chapter02', '冰上梅露露', '冰上梅露露is a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 495, '冰上梅露露', '长枪', '冰上梅露露rushes in and is also pierced by the Spear alongside月代雪.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 496, '不死的能力', '冰上梅露露', '冰上梅露露loses her Immortality Ability after the Witch Factors are reclaimed.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 497, '橘雪莉', '自杀委托', '橘雪莉''s act of killing远野汉娜is motivated by a suicide request, which二阶堂希罗interprets as an act of imagining another''s feelings and acting for them.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 498, '橘雪莉', '监牢', '橘雪莉mentions living in a prison cell, which forms part of the context for her emotional state and beliefs.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 499, '旁白', '监牢', 'The narrator explains that the characters have had to continue staying in the prison for a week.<SEP>旁白recalls the time spent with二阶堂希罗in the监牢, comparing it to their middle school relationship.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 500, '月代雪', '监牢', '月代雪在监牢中透露对话被监听，并指出她们这些魔女无法平安离开这座孤岛上的监牢。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 501, '紫藤亚里沙', '魔女因子', '紫藤亚里沙''s plan to kill everyone is based on the belief it will stop tragedy, which二阶堂希罗counters by explaining witch factors persist.<SEP>紫藤亚里沙observes that the harmless nature of the witch factor leads to a lack of preventive measures by humans.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 502, '大魔女', '魔女因子', 'Before disappearing, the Great Witch left a message about transforming into witch factor, which冰上梅露露believes she did.<SEP>The Great Witch created or used the witch factor as a curse to transform humans into monsters as a method of revenge.<SEP>The Great Witch created the Witch Factor curse as a method of revenge to turn humans into monstrous witches.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 503, '咒术', '魔女因子', 'The witch factor is identified as a curse or technique used for transformation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 504, '怪物', '魔女因子', 'The witch factor transforms humans into monsters, which are one type of "witch".', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 505, '人类', '魔女因子', 'The Witch Factor is a curse designed to transform humans into monsters as an act of revenge.<SEP>Humans carry Witch Factor, and their malice and mental state are the medium for its spread.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 506, '月代雪', '魔女因子', 'The relation between **月代雪 (Tsukishiro Yuki)** and **魔女因子 (Witch Factor)** is central to her identity, powers, and grand plan. As the Great Witch, 月代雪 created the Witch Factor by splitting her own soul, an act tied to her revenge against humanity. She transformed her very existence into this factor and spread it globally. The Witch Factor is implanted into others, granting them immortality as a side effect, and it propagates through human malice, which 月代雪 actively works to spread to ensure its effective dissemination.

月代雪 can control the Witch Factor, using it as a primary weapon. Her overarching plan involves causing the Witch Factors within all of humanity to go out of control, using this as a catalyst to bring about human extinction while striving to minimize any unexpected effects that could disrupt her design. She discreetly spreads the factor among humans for this purpose. Paradoxically, the Witch Factor she spread is also a key component enabling the magic used to kill witches.

月代雪''s physical body is composed of elements that include the Witch Factor once owned by 樱羽艾玛 (Sakuraba Emma). In the culmination of her plan, she aims to absorb and reclaim all Witch Factors back into her own body. Her stated goal for this reclamation is twofold: to erase the Witch Factor curse from the world and, by extension, to erase the existence of the Great Witch herself. An alternative viewpoint within her plan suggests she intends to transform all her Witch Factors into a harmless form and remove them.', 13, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 507, '典狱长', '魔女因子', '典狱长mentions the worldwide spread of the witch factor as the reason for their ongoing efforts.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 508, '灭绝计划', '魔女因子', '魔女因子is the primary weapon being used in the Great Witch''s plan to exterminate humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 509, '杀死魔女的魔法', '魔女因子', 'The Witch Factor has a critical vulnerability to the Magic to Kill Witches, which can reverse its immortality effect.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 510, 'Murder', '宝生玛格', '宝生玛格is accused by二阶堂希罗of being the perpetrator of a murder motivated by love in a previous world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 511, 'Cold Reading', '宝生玛格', '宝生玛格initially dismisses二阶堂希罗''s claim as potentially being Cold Reading, showing her skepticism.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 512, '宝生玛格', '魔女化', '宝生玛格questions the necessity of Witchification and rejects the idea that it is related to escaping their prison.<SEP>宝生玛格completed the魔女化process before her execution, which places a significant strain on her mental state.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 513, '宝生玛格', '整人节目', '宝生玛格criticizes and rejects the prank show proposal as unconvincing, poorly scripted, and in bad taste.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 514, '宝生玛格', '欺诈', '宝生玛格recognizes and accuses二阶堂希罗of using persuasive tactics commonly associated with fraud.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 515, '宝生玛格', '模仿', '宝生玛格uses the模仿magic to replicate the sound of夏目安安''s voice to neutralize her brainwashing effect.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 516, '宝生玛格', '魔女审判', '宝生玛格is operating within the context of the魔女审判, using her observations from it to question and seek guarantees from二阶堂希罗.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 517, '宝生玛格', '情报', '宝生玛格is attempting to extract the情报that二阶堂希罗holds in order to decide her own strategic position.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 518, '宝生玛格', '泽度可可', '宝生玛格analyzes泽度可可''s psychological state, identifying her逃避behavior as a defense mechanism and suggesting forceful intervention to make her face reality.<SEP>宝生玛格observes泽度可可''s behavior and analyzes it as an act of avoidance or escape.<SEP>泽度可可disagrees with宝生玛格''s lighthearted view on punishment, insisting wrongdoers should be punished.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 519, 'Failure', '宝生玛格', '宝生玛格states that if they逃避, the only outcome waiting for them is failure, framing it as a consequence of inaction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 520, 'Poker', '宝生玛格', '宝生玛格uses the analogy of Poker to explain to二阶堂希罗their limited strategic options, emphasizing that choosing to "fold" is not an option.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 521, 'Plan', '宝生玛格', '宝生玛格considers the Plan as one of the strategic options available, alongside finding another method, within the Poker analogy.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 522, '信任', '宝生玛格', '宝生玛格is highly skeptical of claims of trust, accusing二阶堂希罗of lying about trusting the group.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 523, '宝生玛格', '牵绊', '宝生玛格dismisses the idea of bonds as laughable and accuses二阶堂希罗of not believing his own words.', 1, X'');
