INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 597, 'Family', '橘雪莉', '橘雪莉, after her experiences, feels family is precious and wants to return home to be spoiled by them.<SEP>橘雪莉expresses having learned the preciousness of family and wants to reconnect with them.', 2, X'');
