INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 600, '月代雪', '橘雪莉', '橘雪莉expresses suspicion towards月代雪''s behavior, interpreting it as a sign that she does not truly want to destroy humanity.<SEP>橘雪莉opposes月代雪''s plan, declaring intent to dismantle it as a detective, stating it benefits no one.', 2, X'');
