INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 608, '大魔女', '魔女安息仪式', 'The successful completion of the Witch''s Rest Ritual will cause the Great Witch to be incarnated.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 609, '大魔女', '月代雪', '月代雪is identified as the Great Witch who has been resurrected.<SEP>月代雪is revealed to be the person possessed by and acting as the Great Witch.<SEP>月代雪is identified as the大魔女, an entity with the power to bring about human extinction.<SEP>月代雪is referred to as the Great Witch, indicating she is the source of magical power.<SEP>月代雪was one of the大魔女, the ruling witches of魔女之岛, and was the youngest and most skilled.<SEP>月代雪states that by absorbing all魔女因子, the大魔女will disappear.<SEP>月代雪''s reclamation of the Witch Factors will cause the Great Witch to disappear.', 7, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 610, '仪式', '大魔女', 'The ritual is performed with the specific purpose of summoning and revealing the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 611, '凭依物', '大魔女', 'The possessed object is the medium through which the Great Witch has been attaching herself to the characters.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 612, '城崎诺亚', '大魔女', '城崎诺亚observes that the group''s bodies reverted to normal when the Great Witch appeared.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 613, '大魔女', '魔法少女', '魔法少女and大魔女are discussed as related concepts within a hierarchical magical system, with大魔女representing a higher level.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 614, '大魔女', '泽度可可', '泽度可可expresses confusion and fear about the concept of a大魔女and rejects involvement in related events.<SEP>泽度可可expresses fear and confusion about being forced to fight against the大魔女.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 615, '人类少女', '大魔女', 'According to the letter, the Great Witch adopted a human girl.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 616, '大魔女', '诅咒', 'The Great Witch spread a curse to humanity, transplanting witch factor to make them fight forever.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 617, '大魔女', '魔女化', 'The魔女化(witchification) process is described as a curse left by the大魔女(Great Witch).', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 618, '大魔女', '讯息', 'The Great Witch on the island is the source of the message containing the prophecy and her wishes.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 619, '大魔女', '预言', 'The Great Witch''s message includes a prophecy foretelling stagnation and a fate of destruction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 620, '复仇', '大魔女', 'The Great Witch explicitly states in her message that she does not wish to seek revenge against humans.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 621, '大魔女', '幸福', 'The Great Witch expresses a desire for月代雪to be happy in her message.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 622, '大魔女', '魔法', '魔法is a power that originates from and is dependent on the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 623, '泽度可可', '直播', '泽度可可identifies直播as her primary skill, contrasting it with the demands of combat.<SEP>泽度可可uses livestreaming to connect with alternate versions of herself.<SEP>泽度可可hosts a live stream to solicit information and evidence from a global audience.<SEP>泽度可可is actively hosting and engaging with the audience during a live stream event.', 4, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 624, '泽度可可', '魔女化', '泽度可可has completed the process of becoming a witch, which changes her mindset about hiding.<SEP>泽度可可''s ability to connect via livestream is linked to her level of witchification.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 625, '千里眼', '泽度可可', '泽度可可possesses the magical ability千里眼, which is suggested for use in a support role during combat.<SEP>泽度可可uses clairvoyance to gather information from alternate timelines, which places a physical burden on her.<SEP>泽度可可possesses and uses the千里眼clairvoyance ability to gather information from other worlds.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 626, '另一个时间轴上的魔女化的泽渡可可', '泽度可可', '泽度可可previously accessed information from another timeline''s witchified version of herself.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 627, '泽度可可', '魔法', '泽度可可uses magic, specifically千里眼, which places an increasing physical and informational burden on her.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 628, '平行世界', '泽度可可', '泽度可可uses her千里眼to perceive numerous平行世界, which increases the informational burden her brain must process.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 629, '泽度可可', '米莉亚大叔', '泽度可可uses the nickname "米莉亚大叔" and the metaphor of a bomb disposal expert to describe佐伯米莉亚''s inability to handle a fragile person.<SEP>泽度可可references the use of米莉亚大叔''s magic as the means to achieve complete information sharing within the group.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 630, '打倒魔王的勇者', '泽度可可', '泽度可可compares the situation to the story archetype of打倒魔王的勇者, expressing her discomfort and desire to not be involved.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 631, 'Defense Mechanism', '泽度可可', '泽度可可exhibits a psychological defense mechanism characterized by逃避and pretending not to understand, which protects her mind from fear and anxiety.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 632, 'Reality', '泽度可可', '泽度可可is actively逃避reality, refusing to accept the abnormal situation, which is contrasted with the need to confront it to avoid走向毁灭.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 633, 'Police', '泽度可可', '泽度可可questions the purpose of the Police''s arrival, though it is stated to be unrelated to their situation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 634, '泽度可可', '逃避现实', '泽度可可''s primary action and state is escaping reality, refusing to accept her circumstances.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 635, '气球', '泽度可可', '泽度可可reacts with surprise to the revelation that城崎诺亚might be the artist known as "Balloon".', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 636, '我推', '泽度可可', '泽度可可finds personal satisfaction and purpose in watching我推, which she prioritizes over facing harsh reality.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 637, '泽度可可', '除夕夜连续无差别杀伤案', '泽度可可is revealed to be the sole survivor of the除夕夜连续无差别杀伤案, which is the source of her psychological trauma.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 638, '心理创伤', '泽度可可', '泽度可可suffers from心理创伤as a direct result of surviving the violent除夕夜连续无差别杀伤案.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 639, '泽度可可', '自推', '泽度可可exhibits an intense dependence on自推, which二阶堂希罗interprets as a coping mechanism for her trauma.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 640, '泽度可可', '爷爷', '泽度可可expresses worry for爷爷''s health and well-being in a past conversation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 641, '杀人犯', '泽度可可', '泽度可可recounts the traumatic event where a murderer approached and caused the death of泽度可可''s family.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 642, '月代雪', '泽度可可', '泽度可可suggests月代雪''s long life might cause forgetfulness or inconsistency, offering a possible explanation for her behavior.<SEP>泽度可可confronts月代雪with the Great Witch''s message, accusing her of betraying the witch''s wish by pursuing revenge.<SEP>泽度可可suggests月代雪abandon her serious plan and instead join a fun livestream, offering an alternative focus.<SEP>泽度可可mocks月代雪''s expression of pain and effort, calling her stupid and saying such a tragic role is only for junior high school age.', 4, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 643, '弹幕', '泽度可可', '泽度可可requests the audience, especially knowledgeable viewers, to post comments (弹幕) during the live stream.<SEP>泽度可可encourages the live stream audience, particularly knowledgeable viewers, to post comments (danmaku).', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 644, '泽度可可', '记忆', '泽度可可states that all information and memories, including those from other worlds, have been shared among the group of 13 using magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 645, '泽度可可', '讯息', '泽度可可discovers and reveals the content of a message left by the Great Witch on the island, based on audience input.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 646, 'Act03_Chapter02', '泽度可可', '泽度可可is a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 647, '13个人', '泽度可可', '泽度可可is part of a group of thirteen individuals who have completely shared their intelligence.<SEP>泽度可可is part of the group of 13 people among whom all intelligence has been shared.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 648, '屏幕前的家人', '泽度可可', '泽度可可receives critical information about the Great Witch''s message from the live stream audience (the family in front of the screen).', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 649, '共享情报', '泽度可可', '泽度可可coordinates and confirms that all intelligence among the group has been shared using external magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 650, '泽度可可', '超级绝密情报', '泽度可可requests the audience to provide super-secret information that is unknown to the 13 individuals.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 651, '100亿万粉丝', '泽度可可', '泽度可可appeals to her global audience of "100亿万粉丝" during her live stream for information.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 652, '泽度可可', '能证明大魔女说的是错的证据', '泽度可可solicits evidence from her live stream audience to prove the "Great Witch" is wrong.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 653, '悲剧女主角', '泽度可可', '泽度可可mocks the concept of a悲剧女主角, criticizing the prolonged adoption of a tragic persona.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 654, '孤岛', '泽度可可', '泽度可可强烈表达不想待在孤岛，要求放她回去，反映出对无法回家的痛苦。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 655, '城崎诺亚', '魔女化', '城崎诺亚undergoes "魔女化" (witch transformation) as a result of the intense emotional distress caused by the stimulation of her trauma.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 656, '精神的魔女化', '魔女化', '精神的魔女化(spiritual witchification) is a specific aspect of the broader魔女化(witchification) process.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 657, '肉体的魔女化', '魔女化', '肉体的魔女化(physical witchification) is a specific aspect of the broader魔女化(witchification) process.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 658, '月代雪', '魔女化', '月代雪observes the process of魔女化in humans with magic aptitude as an unintended consequence of the witch factor.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 659, 'Murder Case', 'System Options', 'One of the system options states that a murder case will occur, which aligns with二阶堂希罗''s prediction about the environment.', 1, X'');
