INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 664, 'Brainwashing', 'System Options', 'Brainwashing is one of the magical abilities listed in the System Options.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 665, 'Nijika Shiro', 'Sakuraba Emma', 'Nijika Shiro is determined to proceed on their mission and avoids looking back at Sakuraba Emma.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 666, 'Nijika Shiro', 'The Witch''s Repose Ritual', 'Nijika Shiro''s sole stated objective is to reach The Witch''s Repose Ritual.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 667, 'Nijika Shiro', 'The Pen', 'The Pen evokes a powerful emotional response in Nijika Shiro, nearly causing them to crush it due to associated memories.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 668, 'Koyuki', 'Nijika Shiro', 'Nijika Shiro intends to meet Koyuki in order to judge her for her crimes.', 1, X'');
