INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 670, 'Hasumi Ria', 'Nijika Shiro', 'Hasumi Ria draws her sword on Nijika Shiro, calling them a monster and expressing clear hostility, which Nijika Shiro ignores.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 671, 'Nijika Shiro', 'The Monster', 'Nijika Shiro is perceived as The Monster by other characters, including Hasumi Ria.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 672, 'Nijika Shiro', 'The Plan', 'Nijika Shiro is determined to suppress all feelings to advance The Plan quickly.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 673, 'Nijika Shiro', 'The Pocket', 'Nijika Shiro reaches into The Pocket to retrieve The Pen, which is linked to a memory.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 674, 'Nikaido Hiro', 'Sakuraba Emma', 'Nikaido Hiro warns Sakuraba Emma to stay away during his transformation and avoids looking at her to protect her.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 675, 'The Monster', 'Zed Coco', 'Zed Coco expresses fear upon the appearance of The Monster.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 676, 'Hasumi Ria', 'Hikami Meruru', 'Hasumi Ria reacts to protect Hikami Meruru from Nijika Shiro''s confrontation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 677, 'Hasumi Ria', 'The Rapier', 'Hasumi Ria draws The Rapier and points it at Nijika Shiro as a hostile action.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 678, 'The Monster', 'The Thirteen Apprentice Witches', 'The Thirteen Apprentice Witches, as a group, are fearful and perceive there to be more than one monster.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 679, 'The Drawing Room', 'The Guards', 'The Guards block the exits of The Drawing Room, controlling the movement of those inside.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 680, 'Koyuki', 'Nikaido Hiro', 'Nikaido Hiro reflects that a conversation with Koyuki helped slow his witch transformation process at the last moment.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 681, 'The Corridor', 'The Imprisoned Girls', 'The imprisoned girls gather in The Corridor and react with fear upon seeing Nijika Shiro.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 682, '【互换】魔法', '其他世界的记忆', 'The失控of the【互换】魔法is speculated to have caused the sharing of其他世界的记忆among the characters.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 683, 'The Great Witch', 'Witch Factor', 'The Great Witch transformed her very being into Witch Factor, which constitutes her essence.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 684, 'Witch Factor', 'Yuki', 'Yuki created and spread the Witch Factor over a long period as the core mechanism of the revenge plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 685, 'Witch Factor', 'Witch-Killing Magic', 'The Witch-Killing Magic forces the Witch Factor within all humans to go out of control, leading to their death.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 686, 'Witch Factor', '月代雪', '月代雪has spent a long time spreading Witch Factor throughout the world''s human population as a weapon to achieve her goal.<SEP>月代雪confirmed the Witch Factor had spread to all humans, making its further diffusion unnecessary for her plan.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 687, 'Humanity', 'Witch Factor', 'Witch Factor has deeply infiltrated humanity and is the mechanism that will trigger their transformation into Witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 688, 'Witch', 'Witch Factor', 'When Witch Factor goes out of control within a human, it causes them to transform into an immortal Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 689, 'Humanity', 'The Great Witch', 'The Great Witch is plotting revenge against humanity, a fact acknowledged even by those who seek to revive her.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 690, 'Gathering Of Magical Girls', 'The Great Witch', 'The gathering of magical girls is specifically proposed as the ritual method to revive the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 691, '杀意', '杀死魔女的魔法', 'The杀意(killing intent) is identified as a potential trigger for the杀死魔女的魔法(magic to kill the witch).', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 692, '月代雪', '杀死魔女的魔法', '月代雪plans to use the Kill the Witch Magic as the final step in the human extinction plan.<SEP>月代雪possessed the magic to kill a witch but chose to entrust it to樱羽艾玛instead of using it herself.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 693, '政府开发的药物', '杀死魔女的魔法', 'The drug developed by the government has the same function as the Kill the Witch Magic but cannot deal with witch factors.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 694, '第三个人', '霸凌', 'The第三个人was a victim of霸凌(bullying), which caused her great suffering.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 695, '自杀', '霸凌', 'The霸凌(bullying) directly led to the自杀(suicide) of the third person.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 696, '月代雪', '霸凌', '月代雪was a victim of prolonged and severe bullying, which ultimately led to her suicide.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 697, '典狱长', '凶杀案', '典狱长questions the need for a witch trial since no凶杀案(murder case) has occurred yet.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 698, '城崎诺亚', '安安', '城崎诺亚''s psychological trauma and secret are triggered because安安saw her drawings.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 699, '城崎诺亚', '心理创伤', '城崎诺亚''s psychological trauma is linked to her secret about her drawings being seen, which is her motive for potential actions.<SEP>城崎诺亚possesses psychological trauma related to her painting, which is deliberately triggered by external criticism.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 700, '城崎诺亚', '手画的画', '城崎诺亚is the creator of the hand-drawn painting, which is tied to her psychological trauma and emotional state.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 701, '城崎诺亚', '彩色的眼泪', '城崎诺亚exhibits the phenomenon of "彩色的眼泪" (colorful tears) during her emotional breakdown and magical transformation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 702, '会客厅', '城崎诺亚', '城崎诺亚is in the会客厅, playing with its furnishings.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 703, 'Drawing', '城崎诺亚', '城崎诺亚creates drawings but refuses to show them to anyone, claiming it is her freedom and that she is bound by an agreement.', 1, X'');
