INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 705, '城崎诺亚', '气球', '城崎诺亚is accused by二阶堂希罗of being the mysterious street artist known by the alias "Balloon".', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 706, '城崎诺亚', '魔法', '二阶堂希罗accuses城崎诺亚of using magic as the method to create the paintings attributed to her alias.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 707, '城崎诺亚', '画作', '城崎诺亚is associated with the creation of paintings, which are publicly praised but allegedly made with magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 708, '城崎诺亚', '街头艺术家', '二阶堂希罗accuses城崎诺亚of being a street artist, specifically identifying her as the mysterious figure "Balloon".', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 709, '城崎诺亚', '月代雪', 'The relation between **城崎诺亚 and 月代雪** is characterized by 城崎诺亚''s persistent, analytical, and confrontational attempts to connect with and understand 月代雪. This dynamic begins with 城崎诺亚 prompting a revelation from 月代雪 and is defined by a series of direct engagements where 城崎诺亚 questions 月代雪''s motives and logic.

城崎诺亚 consistently analyzes and challenges 月代雪''s stated positions. They accuse 月代雪 of lying about the depth of her hatred for humanity and, more specifically, of being dishonest about revenge being her sole objective. 城崎诺亚 questions the logic behind 月代雪''s chosen methods and directly challenges her commitment to this path of vengeance, suggesting she should focus on happier activities instead.

A central theme in this relation is 城崎诺亚''s effort to find common ground and forge a personal connection. They frequently compare 月代雪''s behavior—such as her changing decisions—to their own tendencies, framing such actions as normal. 城崎诺亚 perceives 月代雪 as not fundamentally different from themselves and repeatedly expresses a desire to be friends. This offer of friendship is explicitly distinguished from past human behavior, and 城崎诺亚 disagrees with any distinction 月代雪 makes that would prevent such a relationship.', 9, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 710, 'Act03_Chapter02', '城崎诺亚', '城崎诺亚is a participant in the events and dialogue that take place within Act03_Chapter02.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 711, '不会杀死魔女的魔法', '城崎诺亚', '城崎诺亚询问不会杀死魔女的魔法是否就是能让她们免于一死的魔法，寻求对生存希望的理解。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 712, '典狱长', '诅咒', '典狱长reports that the curse has been lifted, resulting in most people leaving and a significant increase in free time.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 713, '典狱长', '审判', '典狱长在审判开始后几乎没开过口，保持着令人毛骨悚然的沉默，俯视着其他角色。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 714, '月代雪', '洗脑', '月代雪uses the洗脑magic to stop the protagonists'' movements and force them to surrender.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 715, '希望', '月代雪', 'For月代雪, the concept of hope is the sole remaining motivation that fuels her vengeful purpose.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 716, '岛', '月代雪', '月代雪states there were things she could not confide to the people on the island, highlighting her isolation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 717, '格', '魔法', '格questions whether communication is fundamentally dependent on the use of magic, introducing the theme of magic''s societal role.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 718, '月代雪', '魔法', '月代雪uses魔法, which originates from the魔女因子they spread and reclaimed, to immobilize and control others.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 719, '世间的秩序', '魔法', 'The magic of Apprentice Witches is considered likely to disrupt the order of the world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 720, '整人节目', '气球', 'The script of the proposed prank show includes revealing the true identity of the artifact known as "Balloon".', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 721, '共享情报', '米莉亚大叔', '米莉亚大叔provided the magic method that enabled the complete sharing of information among the group.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 722, '月代雪', '艾玛', '艾玛reunites with月代雪, her old friend, but experiences complex and conflicted emotions upon seeing her.<SEP>月代雪gave魔女杀手魔法to艾玛and pretended to be her friend as part of her necessary plan to monitor humans.<SEP>月代雪''s plan is disrupted by艾玛''s death, forcing her to find a new replacement.<SEP>月代雪entrusted her复仇计划and the fate of humanity to艾玛.', 4, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 723, '月代雪', '赤黑色的液体', '月代雪identifies the blackish-red liquid as the blood of witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 724, '月代雪', '魔女的因子', '月代雪describes the witch factor as a seed that will continue to be sown from the witches'' blood.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 725, '月代雪', '绝望', '月代雪states that her resurrection signifies despair and that a good outcome is impossible.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 726, '复仇计划', '月代雪', '月代雪initiated and long pursued the复仇计划but ultimately entrusted its outcome to others, leading to its abandonment.<SEP>月代雪expresses that her复仇之心has rusted and she has ultimately failed to carry out her复仇计划.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 727, '典狱长', '月代雪', '月代雪states that their conversation is being monitored by the典狱长, making a peaceful return impossible.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 728, '人类', '月代雪', 'The relation between **人类 (Humanity)** and **月代雪 (Tsukishiro Yuki)** is defined by her role as a vengeful judge and executioner who has condemned humanity to extinction. Acting as a judge, 月代雪 finds humanity guilty of eradicating the original witch and sentences them to immediate execution. This verdict is driven by her belief that humanity is responsible for the historical persecution and killing of witches, having taken everything from her. She views this extermination as both a rational correction of human errors and an act of revenge for the witches'' suffering, declaring the judgment final.

Her condemnation is rooted in specific accusations against humanity. She argues that humans are the ones who discriminate against and have attempted to exterminate witches, questioning their wisdom and actions. She believes all humans possess an inherent potential for evil and cannot be guaranteed to be good. To enact her revenge, she created the 魔女因子 (Witch Factor) curse specifically to inflict suffering on humanity as punishment for the destruction of the witches.

However, a secondary, more observational dimension to her relation with humanity exists. Having witnessed human-caused extinction and their rapid technological advancement, she believes she must closely monitor humans due to the threat they pose. This complex engagement is hinted at in her decision to entrust humanity''s fate to another, 艾玛 (Emma), while questioning if her deep involvement with humans has caused her 复仇之心 (heart of vengeance) to rust. Ultimately, 月代雪''s relation to humanity is that of a hostile judge targeting them for annihilation, motivated by past sins, a desire for retribution, and a perceived need for corrective justice.', 13, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 729, '感情麻木', '月代雪', '月代雪wonders if her感情麻木is due to the passage of too much time.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 730, '复仇之心', '月代雪', '月代雪states that her复仇之心has rusted.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 731, '月代雪', '温柔的浅眠', '月代雪expresses a desire to immerse herself in a温柔的浅眠.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 732, '对话监听', '月代雪', '月代雪states that their对话监听prevents her and樱羽艾玛from returning home safely, even if she abandons her plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 733, '复仇', '月代雪', '月代雪cites revenge as the motivation and justification for her plan to exterminate humanity.<SEP>月代雪''s actions are driven by a desire for revenge against humanity for the death of her同胞.<SEP>复仇is the primary motive for月代雪''s actions, which she describes as a form of collaboration with humanity.<SEP>Revenge is the primary motivation driving月代雪''s actions and her stated purpose for seeking human extinction.<SEP>月代雪states that revenge is her sole long-cherished wish, which drives her actions and internal conflict.<SEP>月代雪has pursued revenge but considers setting it aside temporarily, viewing continuing forward as a form of forgetting.', 6, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 734, '感情', '月代雪', '月代雪discusses感情as an expression of意志, which she sees as the rational core of her long-held purpose.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 735, '仪礼剑', '月代雪', 'The仪礼剑floats near月代雪as part of the unfolding events.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 736, '月代雪', '钢笔', '月代雪received a钢笔from二阶堂希罗, which brought her warmth and comfort.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 737, 'Extermination Of Humanity', '月代雪', '月代雪states that she must exterminate humanity, framing it as her necessary mission.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 738, 'Revenge', '月代雪', '月代雪''s actions are driven by a desire for revenge against humanity for past treatment, which she believes will end the cycle.<SEP>月代雪states that revenge is her sole, long-cherished wish, which drives her actions.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 739, 'Act03_Chapter02', '月代雪', '月代雪is a participant in the dialogue that occurs within the chapter titled Act03_Chapter02.<SEP>The dialogue in Act03_Chapter02 features月代雪as a participant.<SEP>月代雪is a participant in the events and dialogue that take place within Act03_Chapter02.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 740, '月代雪', '灭绝', 'The extinction of humanity is the ultimate objective of月代雪''s revenge plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 741, '上古的魔女们', '月代雪', '月代雪differentiates herself from the Ancient Witches, believing their pacifist creed led to failure, while her path of conflict is correct.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 742, '古训', '月代雪', '月代雪believes the Ancient Witches'' adherence to the non-conflict creed was a mistake that resulted in their demise.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 743, '月代雪', '裁决', '月代雪appoints herself as the one to judge and hold humanity accountable through extinction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 744, '智慧的生命', '月代雪', '月代雪criticizes the Ancient Witches for mistakenly believing humans were intelligent life like themselves.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 745, '月代雪', '魔女因子的诅咒', '月代雪aims to completely erase the Curse of the Witch Factors from the world.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 746, '月代雪', '长枪', '月代雪is pierced by the Spear as part of her sacrificial act.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 747, '作为人类诞生的罪', '月代雪', '月代雪accuses humans of bearing the inherent sin "作为人类诞生的罪" and demands they atone for it.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 748, '月代雪', '灭绝人类', '月代雪''s primary goal and plan is to achieve the complete extinction of humanity.<SEP>月代雪''s actions of monitoring and spreading魔女因子are ultimately aimed at finding an opportunity for灭绝人类.<SEP>月代雪mentions the goal of human extinction as something to be temporarily set aside.', 3, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 749, '月代雪', '魔女杀手魔法', '月代雪claims to possess the "魔女杀手魔法" and can use it to kill witches.<SEP>月代雪gave the魔女杀手魔法to樱羽艾玛as a necessary action for her plan to control the spread of witch factor.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 750, '处决魔女', '月代雪', '月代雪explains the methods and reality of witch executions based on her knowledge and experience.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 751, '怪物【魔女】', '月代雪', '月代雪created monstrous witch-like beings using魔女因子and compares their fragility to that of regular witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 752, '人类灭绝计划', '月代雪', '月代雪is the proponent and executor of the plan to cause human extinction.<SEP>月代雪is the primary advocate and determined executor of the人类灭绝计划, inviting others to join her.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 753, '月代雪', '雪', '雪challenges月代雪''s statement, implying it is biased and based solely on her own position.<SEP>月代雪is the same person as雪, the sole surviving witch from the island who initiated the revenge plan.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 754, '人类灭绝', '月代雪', '月代雪declares her intention to execute the extermination of all humanity as a predetermined event.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 755, '月代雪', '魔女之岛', '月代雪states that魔女之岛will once again soar in the sky, indicating her control or influence over it.<SEP>月代雪originated from and was the sole survivor of魔女之岛after its destruction.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 756, '天使', '月代雪', '月代雪declares she will travel the world as an angel to spread the gospel of death to all humans.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 757, '月代雪', '福音', '月代雪''s stated mission as an angel is to spread a gospel, which she defines as granting death to humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 758, '月代雪', '自然', '月代雪states it is time to return the world to nature, which is the stated goal of her plan to exterminate humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 759, '原初的魔女', '月代雪', '月代雪bases the accusation and judgment against humanity on the crime of eradicating the original witch.<SEP>月代雪identifies as one of the original witches, claiming they are a superior race to humans.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 760, '感情用事', '月代雪', '月代雪classifies her own revenge-driven actions as acting on emotion.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 761, '同胞', '月代雪', '月代雪''s复仇is driven by the emotions (anger, sadness, hatred) stemming from the death of her同胞.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 762, '月代雪', '灭绝计划', '月代雪is the architect and executor of the plan to exterminate humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 763, '孤岛', '月代雪', '月代雪and the other witches lived on and defended themselves on the孤岛when it was attacked by humans.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 764, '天灾地变', '月代雪', '月代雪mentions triggering natural disasters as a method to achieve human extinction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 765, '方舟', '月代雪', '月代雪considers the possibility of humans surviving disasters by using an ''ark'', which influences her need for close observation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 766, 'Human Execution', '月代雪', '月代雪has decided on and will enforce the execution of humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 767, 'Return To Nature', '月代雪', '月代雪proposes that humanity should return to nature or be reduced to nothingness as an alternative fate.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 768, 'Human Guilt', '月代雪', '月代雪uses the concept of humanity being born with sin to justify the execution.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 769, 'Grace Period', '月代雪', '月代雪justifies the execution by stating that a sufficient grace period has been given, referencing human world practices like the death penalty.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 770, 'Deceased Witches', '月代雪', '月代雪carries the hatred of all deceased witches, which compels her to continue her actions.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 771, '月代雪', '术法', '月代雪developed and completed the术法, using梅露露as a test subject, to enact the魔女因子curse.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 772, '月代雪', '讨论', '月代雪reluctantly agrees to continue the discussion, as demanded by夏目安安and二阶堂希罗, though she believes it is a futile waste of time.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 773, '刑罚', '月代雪', '月代雪decrees the punishment of annihilation for humanity, stating it must be equal to the extinction suffered by the witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 774, 'Plan', '月代雪', '月代雪devised and orchestrated the Plan over centuries, with the ultimate goal of witnessing humanity''s self-inflicted extinction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 775, '不会杀死魔女的魔法', '月代雪', '月代雪提出使用不会杀死魔女的魔法，计划将所有魔女因子转化为无害形式来拯救魔女们。', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 776, 'Humanity', '月代雪', '月代雪''s plan targets humanity for transformation into Witches by activating the Witch Factor within them.<SEP>月代雪views Humanity as the enemy, judging them deserving of extinction by their own hands as retribution for exterminating witches.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 777, '审判过家家', '月代雪', '月代雪declares that the "pretend trial" should end, as further argument is a waste of time.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 778, '技术革新', '月代雪', '月代雪cites rapid human技术革新, such as内燃机and核裂变, as the primary reason for her need to maintain constant vigilance.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 779, '战乱', '月代雪', '月代雪游走各地and avoids战乱as part of her strategy to monitor humans without drawing attention.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 780, '月代雪', '灭绝其他种族的权利', '月代雪claims the right to exterminate other races and states she will guarantee and exercise this right.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 781, '力量', '月代雪', '月代雪states that rights are guaranteed by power, establishing power as the foundation of her claim.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 782, '月代雪', '邪恶魔女', '月代雪accepts the label of an evil witch and blames humanity for forcing her onto that path.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 783, '月代雪', '灭绝人类计划', '月代雪formulates and intends to execute a plan to exterminate humanity using the失控的魔女因子and the Magic to Kill Witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 784, '命运', '月代雪', '月代雪declares that the fate of human death is unchangeable and must be accepted.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 785, 'Extinction', '月代雪', '月代雪orchestrates the extinction of humanity by triggering the Witch Factor, intending to end human history.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 786, 'Right To Exterminate', '月代雪', '月代雪claims the right to exterminate humanity, stating that this right is guaranteed and enforced by her power.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 787, '典狱长', '猫头鹰', 'The sound of the猫头鹰''s wings flapping signals the appearance of the典狱长.<SEP>典狱长identifies itself as a可爱猫头鹰(cute owl) responsible for managing the mansion.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 788, '仪礼剑', '魔女安息仪式', 'The Witch''s Rest Ritual requires the magical power of 13 witches to be concentrated on the ceremonial sword.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 789, '典狱长', '审判庭', '典狱长officiates the proceedings in the courtroom, having rung the bell to start.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 790, '审判庭', '赤黑色的液体', 'The blackish-red liquid floods and emerges from within the courtroom.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 791, '仪礼剑', '长枪', 'The Ceremonial Sword transforms into a Spear before being used to pierce月代雪.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 792, '典狱长', '魔女审判', '典狱长is ordered to prepare for the witch trial and does so reluctantly after receiving approval.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 793, '少女们', '魔女审判', 'The魔女审判is intended to judge the少女们, both those who have died and become witches and the current participants as potential new sacrifices.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 794, '这座岛', '魔女审判', 'The witch trial is conducted according to the specific rules of this island.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 795, '典狱长', '钟声', '典狱长rings the钟声to formally commence the proceedings in the审判庭.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 796, '典狱长', '国家机关', '典狱长explains the regulation that state authorities are supposed to execute them before they become full witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 797, '典狱长', '岛屿', 'The典狱长reports on the current slow descent of the island and the need for future map redrawing.<SEP>典狱长reports on the status of the island, noting its altitude is slowly decreasing and maps will need to be redrawn after landing.', 2, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 798, '典狱长', '监狱岛', '典狱长discusses the conditions and violent conflicts occurring on the prison island.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 799, '下一批预备魔女', '典狱长', '典狱长confirms the ongoing search for the next batch of potential witches as part of their work.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 800, '典狱长', '鸟', '典狱长complains that unspecified individuals are overworking the birds, expressing a desire for a long vacation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 801, '参与者们', '证人席', 'The participants, including二阶堂希罗and the others, stand at their respective证人席upon entering the审判庭.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 802, '小雪', '艾玛', '小雪used艾玛, making her an accomplice in the plan to exterminate humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 803, '亚里沙', '堂希罗', '堂希罗thinks about亚里沙''s past crime and guilt, speculating on the causes of her失控.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 804, '失控', '负罪感', '负罪感is identified as one of the causes of亚里沙''s失控.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 805, 'Humanity', 'Plan', 'The Plan is designed to cause the extinction of Humanity as punishment for their past extermination of witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 806, 'Death Backtrack', 'Nikaido Hiro', 'Nikaido Hiro has experienced death backtrack, which reset his body but could not reverse his deep witch transformation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 807, 'Nikaido Hiro', 'Witch''s Requiem', 'Nikaido Hiro is determined to initiate the Witch''s Requiem ritual as a means to save others, despite its cruelty.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 808, 'Iron Bars', 'Nikaido Hiro', 'Nikaido Hiro looks at the iron bars that imprison them, reinforcing his determination to proceed with his plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 809, '13 Witches', 'Witch''s Requiem', 'The Witch''s Requiem ritual requires the gathering of 13 fully transformed witches to be successfully performed.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 810, '13 Witches', 'Witch''s Book', 'The Witch''s Book contains clues left by the girls that specify the need for 13 witches to summon the Great Witch.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 811, '13 Witches', 'Great Witch', 'Gathering 13 witches is the necessary condition to summon the Great Witch, as indicated in the Witch''s Book.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 812, 'Mimuru', 'Narrator', 'The Narrator compares the act of forcing witch transformations on others to the atrocities committed by Mimuru, stating it is even more cruel.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 813, '幸福', '讯息', 'The message from the Great Witch expresses a wish for月代雪''s happiness.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 814, '人类', '杀死魔女的药', 'Humans developed the "Medicine to Kill Witches" as a technological countermeasure against immortal witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 815, '处刑台', '赤黑色的液体', 'The blackish-red liquid initially seeps from the execution platform.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 816, '枪声', '肉块', 'The gunshot is fired with the intent to attack the flesh mass.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 817, '子弹', '肉块', 'The bullet is fired at the flesh mass but is intercepted and burns up in the air before impact.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 818, 'Humanity', 'Witch-Killing Magic', 'The activation of the Witch-Killing Magic will result in the extermination of all humanity as the final step of Yuki''s plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 819, 'Humanity', 'Yuki', 'Yuki''s entire plan is targeted at humanity, aiming for its extermination as an act of revenge.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 820, 'Humanity', 'Kill Emma', 'The option to Kill Emma is presented as a way to temporarily prevent humanity''s extinction by removing the current key to the magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 821, 'Revenge', 'Yuki', 'Yuki''s actions, including spreading Witch Factor and planning the Witch-Killing Magic, are driven by a desire for revenge against humanity.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 822, '上古的魔女们', '智慧的生命', 'The Ancient Witches held the mistaken belief that humans were intelligent life forms comparable to themselves.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 823, '停滞', '讯息', 'The message from the Great Witch contains a mention or prophecy about stagnation.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 824, '毁灭的命运', '讯息', 'The message from the Great Witch contains a prophecy about an accepted fate of destruction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 825, '屏幕前的家人', '讯息', 'The live stream audience relayed the content of the message they received from the Great Witch to泽度可可.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 826, '声音', '屏幕前的家人', 'The live stream audience reported hearing a sound, which was the method of receiving the Great Witch''s message.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 827, '人类灭绝', '杀死艾玛', 'The action of killing樱羽艾玛is proposed as a way to temporarily prevent or delay human extinction.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 828, '人类的军队', '魔女之岛', '人类的军队attacked and destroyed魔女之岛, leading to the near-extinction of the witches.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 829, 'Emma Ouka', 'Yuki', 'Yuki used Emma Ouka as a medium to spread Witch Factor and designates her as the key to activating the Witch-Killing Magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 830, 'Arisa Fujito', 'Yuki', 'Arisa Fujito assesses Yuki''s claims and believes she is likely not bluffing.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 831, 'Noah Kinosaki', 'Yuki', 'Noah Kinosaki believes that Yuki may not be lying about her plan.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 832, 'System Option', 'Yuki', 'Yuki presents the System Options, such as killing Emma or letting Yuki kill everyone, to manipulate the outcome.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 833, 'Emma Ouka', 'Witch-Killing Magic', 'Emma Ouka is the key required to activate the Witch-Killing Magic and is its designated inheritor.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 834, 'Emma Ouka', 'Witch Killer', 'Emma Ouka is the current inheritor and holder of the title "Witch Killer," which is the key role for the Witch-Killing Magic.', 1, X'');
INSERT INTO relations (timeline_id, relation_id, source_entity, target_entity, description, weight, vector) VALUES ('3rd_Loop', 835, 'Coco Zato', 'Witch-Killing Magic', 'Coco Zato reacts with despair, believing there is no way to stop the Witch-Killing Magic plan.', 1, X'');
